def test_configuration_lock_covers_defaults_source_registry_and_effective_values():
    """版本相同改内容也改变引用；旧锁不能被 Worker 自报新摘要替换。"""
    baseline = resolve()
    expected = configuration_reference(baseline)
    for name, mutation in (("defaults", "version"), ("defaults", "budget"), ("source", "version"), ("registry", "version")):
        parts = configuration_inputs()
        data = getattr(parts, name).model_dump()
        if mutation == "budget": data["pools"]["io"]["max_attempts"] = 4
        else: data["version"] = "1.0.1"
        replace_part(parts, name, data)
        changed = resolve(parts)
        assert configuration_reference(changed) != expected
        with pytest.raises(ValueError, match="content lock"):
            verify_configuration(changed, expected)
    mutated = baseline.model_copy(deep=True)
    mutated.context.allowed_tools.append("not-granted")
    with pytest.raises(ValueError):
        verify_configuration(mutated, expected)
    assert verify_configuration(baseline, expected) == baseline


def test_task_freezes_query_inputs_flags_and_priority():
    """manual_only 与最大优先级传播；输入快照内容改动不能复用旧引用。"""
    config = resolve()
    key = CollectionTaskKey(job_id="job", job_generation=1, schedule="periodic", cycle_id="cycle", slice_seq=0)
    query = FileQuery(file_id="fixture", byte_digest="sha256:"+"a"*64, page_size=1)
    inputs = InputSnapshot(inputs=[], flags=DependencyFlags(contains_simulated_input=True), publication_policy="manual_only", priority=99)
    task = prepare_collection_task(config, configuration_reference(config), key, query, inputs)
    assert task.priority == 99 and task.context.publication_policy == "manual_only"
    assert task.input_snapshot.flags.contains_simulated_input
    assert len(task.input_snapshot.inputs) == 1
    assert verify_collection_task(task, config, configuration_reference(config)) == task
    data = task.model_dump()
    data["query"]["page_size"] = 2
    changed = type(task)(**data)
    with pytest.raises(ValueError):
        verify_collection_task(changed, config, configuration_reference(config))
    assert restrictive_publication("automatic", "manual_only") == "manual_only"
    with pytest.raises(ValueError): restrictive_publication()


def test_continuous_task_identity_survives_accounting_window():
    """continuous 只按 job/generation/slice_seq；periodic 必须区分 cycle。"""
    from runtime.core.collection_config import collection_task_id
    key = CollectionTaskKey(job_id="job", job_generation=1, schedule="continuous", cycle_id="window-a", slice_seq=7)
    assert collection_task_id(key) == collection_task_id(key.model_copy(update={"cycle_id": "window-b"}))
    assert collection_task_id(key) != collection_task_id(key.model_copy(update={"slice_seq": 8}))
    periodic = key.model_copy(update={"schedule": "periodic"})
    assert collection_task_id(periodic) != collection_task_id(periodic.model_copy(update={"cycle_id": "window-b"}))


